We extend the minimum-window pattern with a per-character upper bound. Two dicts track the needed counts and the current counts, and a counter tracks how many distinct character types are fully satisfied. Additionally we track the maximum character count inside the window; if any character exceeds two we shrink from the left until it is back at most two. The smallest window meeting all three constraints is the answer.

```python
from typing import Dict

def min_window_with_cap(s: str, t: str, cap: int = 2) -> str:
    """Return the smallest substring of s containing all characters of t with per-character cap.

    Args:
        s: The text to search.
        t: The pattern with required character multiplicities.
        cap: The maximum allowed count of any character inside the window.

    Returns:
        The smallest qualifying window, or '' if none exists.

    Examples:
        >>> min_window_with_cap("ADOBECODEBANC", "ABC")
        'BANC'
        >>> min_window_with_cap("aaaaa", "aa")
        'aa'
        >>> min_window_with_cap("abc", "abcd")
        ''
    """
    if not t or len(t) > len(s):
        return ""
    need: Dict[str, int] = {}
    for ch in t:
        need[ch] = need.get(ch, 0) + 1
    have: Dict[str, int] = {}
    satisfied = 0
    required = len(need)
    best = (len(s) + 1, "")
    left = 0
    for right, ch in enumerate(s):
        if ch in need:
            have[ch] = have.get(ch, 0) + 1
            if have[ch] == need[ch]:
                satisfied += 1
        if have.get(ch, 0) > cap:
            while have.get(ch, 0) > cap:
                out = s[left]
                left += 1
                if out in need:
                    if have[out] == need[out]:
                        satisfied -= 1
                    have[out] -= 1
        while satisfied == required and have.get(ch, 0) <= cap:
            if right - left + 1 < best[0]:
                best = (right - left + 1, s[left:right + 1])
            out = s[left]
            left += 1
            if out in need:
                if have[out] == need[out]:
                    satisfied -= 1
                have[out] -= 1
    return best[1]
```

The maximum subset XOR equals the maximum XOR achievable by XORing any subset of the array. We insert each number into a binary trie and greedily try to extend the running answer one bit at a time. At each bit position we prefer the child that complements the current answer's bit. After processing all numbers we return the best we built. This is O(n log max) time and is the standard approach.

```python
from typing import List

class _Node:
    __slots__ = ("children",)
    def __init__(self) -> None:
        self.children = [None, None]

class _Trie:
    def __init__(self) -> None:
        self.root = _Node()
    def insert(self, x: int) -> None:
        node = self.root
        for k in range(31, -1, -1):
            bit = (x >> k) & 1
            if node.children[bit] is None:
                node.children[bit] = _Node()
            node = node.children[bit]
    def best(self, x: int) -> int:
        node = self.root
        result = 0
        for k in range(31, -1, -1):
            bit = (x >> k) & 1
            want = 1 - bit
            if node.children[want] is not None:
                result |= 1 << k
                node = node.children[want]
            elif node.children[bit] is not None:
                node = node.children[bit]
        return result

def max_subset_xor(nums: List[int]) -> int:
    """Return the maximum XOR obtainable by XORing any subset of nums.

    Args:
        nums: A non-empty list of non-negative integers.

    Returns:
        The maximum subset XOR.

    Examples:
        >>> max_subset_xor([3, 10, 5])
        15
        >>> max_subset_xor([0, 0, 0])
        0
    """
    if not nums:
        raise ValueError("nums must be non-empty")
    trie = _Trie()
    for x in nums:
        trie.insert(x)
    best = 0
    for x in nums:
        cand = trie.best(x)
        if cand > best:
            best = cand
    return best
```

We use union-find with path compression and union by rank. Each edge merges the two endpoint sets; at the end the number of distinct root parents equals the number of components. The hash map aspect is that we maintain parent and rank dicts keyed by node, so isolated nodes with no edges are also counted.

```python
from typing import Dict, List, Tuple

def count_components(n: int, edges: List[Tuple[int, int]]) -> int:
    """Count connected components in an undirected graph.

    Args:
        n: Number of nodes labeled 0..n-1.
        edges: List of (u, v) edges.

    Returns:
        Number of connected components.

    Examples:
        >>> count_components(5, [(0, 1), (2, 3)])
        2
        >>> count_components(4, [])
        4
    """
    parent: Dict[int, int] = {i: i for i in range(n)}
    rank: Dict[int, int] = {i: 0 for i in range(n)}

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    for u, v in edges:
        union(u, v)
    roots = {find(i) for i in range(n)}
    return len(roots)
```

A cut at position y on a board of height h splits it into two boards (y x w) and ((h-y) x w), and the cost of the cut plus the cost of cutting each child must sum to the minimum. The cut position must be inside the current board (1..h-1 or 1..w-1). Memoize solve(h, w) over integer dimensions and try every available cut; the answer is the cheapest sum. The cut-cost maps constrain which positions are usable.

```python
from functools import lru_cache
from typing import Dict

def min_cut_cost(height: int, width: int,
                 h_cuts: Dict[int, int], v_cuts: Dict[int, int]) -> int:
    """Minimum cost to cut a board into 1x1 squares given per-cut costs.

    Args:
        height: Initial board height (positive integer).
        width: Initial board width (positive integer).
        h_cuts: Mapping (y position) -> cost of a horizontal cut at that position.
        v_cuts: Mapping (x position) -> cost of a vertical cut at that position.

    Returns:
        Minimum total cost to cut the board into 1x1 squares.

    Examples:
        >>> min_cut_cost(3, 2, {1: 2, 2: 4}, {1: 1})
        9
        >>> min_cut_cost(2, 2, {1: 3}, {1: 2})
        10
    """
    @lru_cache(maxsize=None)
    def solve(h: int, w: int) -> int:
        if h == 1 and w == 1:
            return 0
        best = float('inf')
        for y in h_cuts:
            if 1 <= y <= h - 1:
                cand = h_cuts[y] + solve(y, w) + solve(h - y, w)
                if cand < best:
                    best = cand
        for x in v_cuts:
            if 1 <= x <= w - 1:
                cand = v_cuts[x] + solve(h, x) + solve(h, w - x)
                if cand < best:
                    best = cand
        return int(best)
    return solve(height, width)
```

We compare character frequencies. A window of length equal to the pattern slides over the text; for each position we maintain a count of matches between the window's character frequencies and the pattern's. We use two dicts and increment or decrement a counter of matched character types as the window moves. When the match counter equals the number of distinct pattern characters we have found a permutation.

```python
from typing import Dict

def has_permutation(s: str, pattern: str) -> bool:
    """Return True if some substring of s is a permutation of pattern.

    Args:
        s: The text to search.
        pattern: The pattern string.

    Returns:
        True if any substring of s of length len(pattern) is an anagram of pattern.

    Examples:
        >>> has_permutation("oidbcaf", "abc")
        True
        >>> has_permutation("odicf", "dc")
        False
        >>> has_permutation("aaab", "ab")
        True
    """
    k = len(pattern)
    if k == 0 or k > len(s):
        return k == 0
    need: Dict[str, int] = {}
    have: Dict[str, int] = {}
    for ch in pattern:
        need[ch] = need.get(ch, 0) + 1
    for i in range(k):
        have[s[i]] = have.get(s[i], 0) + 1
    matches = sum(1 for ch in need if have.get(ch, 0) == need[ch])
    if matches == len(need):
        return True
    for i in range(k, len(s)):
        out, inn = s[i - k], s[i]
        if out in have:
            have[out] -= 1
            if have[out] == 0:
                del have[out]
        have[inn] = have.get(inn, 0) + 1
        if out in need:
            if have.get(out, 0) + 1 == need[out]:
                matches += 1
            elif have.get(out, 0) == 0 and out in have:
                matches -= 1
        if inn in need:
            if have[inn] == need[inn]:
                matches += 1
            elif have.get(inn, 0) - 1 == need[inn]:
                matches -= 1
        if matches == len(need):
            return True
    return False
```

We sort points by x, split at the midpoint, recursively solve each half, then consider pairs that straddle the dividing plane. The strip lives in a slab of width delta along x and is sorted by y. We sweep upward through the strip and only check each point against the next few by y (constant-bounded in 3D because of the geometry). To keep the y-sorting efficient we re-sort the strip at each level. Total cost is O(n log^2 n) for the simpler implementation. This illustrates that the closest-pair divide-and-conquer generalizes to higher dimensions.

```python
import math
from typing import List, Tuple

Point = Tuple[float, float, float]

def closest_pair_3d(points: List[Point]) -> float:
    """Return the closest pairwise 3D Euclidean distance.

    Args:
        points: A list of at least two 3D points.

    Returns:
        The minimum pairwise distance.

    Examples:
        >>> closest_pair_3d([(0, 0, 0), (1, 0, 0), (2, 1, 1)])
        1.0
    """
    pts = sorted(points, key=lambda p: p[0])
    def dist(p: Point, q: Point) -> float:
        return math.sqrt(sum((a - b) ** 2 for a, b in zip(p, q)))
    def brute(lo: int, hi: int) -> float:
        d = float('inf')
        for i in range(lo, hi):
            for j in range(i + 1, hi + 1):
                d = min(d, dist(pts[i], pts[j]))
        return d
    def rec(lo: int, hi: int) -> float:
        if hi - lo <= 2:
            return brute(lo, hi)
        mid = (lo + hi) // 2
        mid_x = pts[mid][0]
        d = min(rec(lo, mid), rec(mid + 1, hi))
        strip = [p for p in pts[lo:hi + 1] if abs(p[0] - mid_x) < d]
        strip.sort(key=lambda p: (p[1], p[2]))
        for i in range(len(strip)):
            for j in range(i + 1, len(strip)):
                if (strip[j][1] - strip[i][1]) ** 2 >= d * d:
                    break
                d = min(d, dist(strip[i], strip[j]))
        return d
    return rec(0, len(pts) - 1)
```
